namespace versions {
    int correct(int v, int lo, int hi) { return v < lo ? lo : (v > hi ? hi : v); }
    int ignoresLow(int v, int, int hi) { return v > hi ? hi : v; }
    int ignoresHigh(int v, int lo, int) { return v < lo ? lo : v; }
    int offByOne(int v, int lo, int hi) { return v <= lo ? lo : (v >= hi - 1 ? hi : v); }
    int swapped(int v, int lo, int hi) { return v < lo ? hi : (v > hi ? lo : v); }
}
TEST("passes a correct clamp") { CHECK_EQ(testClamp(versions::correct), 0); }
TEST("catches a clamp that ignores the low end") { CHECK(testClamp(versions::ignoresLow) != 0); }
TEST("catches a clamp that ignores the high end") { CHECK(testClamp(versions::ignoresHigh) != 0); }
TEST("catches an off-by-one near the high end") { CHECK(testClamp(versions::offByOne) != 0); }
TEST("catches a clamp that returns the wrong end") { CHECK(testClamp(versions::swapped) != 0); }

